// lalrMakeSequence wraps a list of action nodes into a single sequence node.
func lalrMakeSequence(stmts []ast.Node) ast.Node {
	if len(stmts) == 0 {
		return &ast.Sequence{}
	}
	if len(stmts) == 1 {
		return stmts[0]
	}
	return &ast.Sequence{Stmts: stmts}
}

